// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title AgentMarketplace
 * @dev A marketplace for AI agents on the HeLa network.
 */
contract AgentMarketplace {
    enum AgentType {
        Trading,
        Farming,
        Scheduling,
        PortfolioRebalancing,
        ContentReply,
        BusinessAssistant
    }

    struct Agent {
        uint256 id;
        address creator;
        string name;
        string description;
        AgentType agentType;
        uint256 price; // Price in HELA to use the agent
        bool isActive;
    }

    uint256 public nextAgentId;
    mapping(uint256 => Agent) public agents;
    mapping(address => uint256[]) public creatorAgents;

    // Fixed 5% marketplace fee
    uint256 public constant MARKETPLACE_FEE_PERCENT = 5;
    address public treasury;

    event AgentRegistered(uint256 indexed id, address indexed creator, string name, AgentType agentType, uint256 price);
    event AgentPurchased(uint256 indexed id, address indexed buyer, address indexed creator, uint256 price);

    constructor(address _treasury) {
        treasury = _treasury;
    }

    /**
     * @dev Register a new agent
     */
    function registerAgent(
        string memory _name,
        string memory _description,
        AgentType _agentType,
        uint256 _price
    ) external {
        uint256 agentId = nextAgentId++;

        agents[agentId] = Agent({
            id: agentId,
            creator: msg.sender,
            name: _name,
            description: _description,
            agentType: _agentType,
            price: _price,
            isActive: true
        });

        creatorAgents[msg.sender].push(agentId);

        emit AgentRegistered(agentId, msg.sender, _name, _agentType, _price);
    }

    /**
     * @dev Purchase/Hire an agent
     */
    function hireAgent(uint256 _agentId) external payable {
        Agent storage agent = agents[_agentId];
        require(agent.isActive, "Agent is not active");
        require(msg.value == agent.price, "Incorrect payment amount");

        uint256 fee = (msg.value * MARKETPLACE_FEE_PERCENT) / 100;
        uint256 creatorShare = msg.value - fee;

        // Transfer funds
        payable(treasury).transfer(fee);
        payable(agent.creator).transfer(creatorShare);

        // In a real implementation, this would grant the buyer access to the agent (e.g., emit an event picked up by an off-chain API)
        emit AgentPurchased(_agentId, msg.sender, agent.creator, msg.value);
    }

    function setTreasury(address _treasury) external {
        // Simple logic for prototype: assume only treasury can set treasury
        require(msg.sender == treasury, "Only treasury can update");
        treasury = _treasury;
    }
}

